content.match(/黑深残属性Tags[\s\S]+人物属性类Tags/gi)[0].match(/<a.+<\/a>/gi).forEach(a=>{
    res.push({title:a.match(/>.+(?=<)/gi)[0].replace('>',''),url:'https://www.wenku8.net/modules/article/'+a.match(/=.+(?=>.+<)/gi)[0].replace(/^=/i,'')+"&page={{page}},{'charset': 'gbk'}",style:{layout_flexGrow:1,layout_flexBasisPercent:0.25}})
})
res.push({title:'人物属性类Tags',url:'',style:{layout_flexGrow:1,layout_flexBasisPercent:1}})
content.match(/人物属性类Tags[\s\S]+特殊属性类Tags/gi)[0].match(/<a.+<\/a>/gi).forEach(a=>{
    res.push({title:a.match(/>.+(?=<)/gi)[0].replace('>',''),url:'https://www.wenku8.net/modules/article/'+a.match(/=.+(?=>.+<)/gi)[0].replace(/^=/i,'')+"&page={{page}},{'charset': 'gbk'}",style:{layout_flexGrow:1,layout_flexBasisPercent:0.25}})
})
res.push({title:'特殊属性类Tags',url:'',style:{layout_flexGrow:1,layout_flexBasisPercent:1}})
content.match(/特殊属性类Tags[\s\S]+排 行 榜/gi)[0].match(/<a.+<\/a>/gi).forEach(a=>{
    res.push({title:a.match(/>.+(?=<)/gi)[0].replace('>',''),url:'https://www.wenku8.net/modules/article/'+a.match(/=.+(?=>.+<)/gi)[0].replace(/^=/i,'')+"&page={{page}},{'charset': 'gbk'}",style:{layout_flexGrow:1,layout_flexBasisPercent:0.25}})
})
res.push({title:'排行榜',url:'',style:{layout_flexGrow:1,layout_flexBasisPercent:1}})
content.match(/排 行 榜[\s\S]+小说搜索/gi)[0].match(/<a[^&\n]+<\/a>/gi).forEach(a=>{
    res.push({title:a.match(/>.+?(?=<)/i)[0].replace('>',''),url:a.match(/\".+(?=\")/gi)[0].replace('"','')+"&page={{page}}",style:{layout_flexGrow:1,layout_flexBasisPercent:0.25}})
})
